/*
 * GitHub emoji shortcode expansion for the cmark-gfm gateway.
 *
 * The shortcode table is generated by buildfile.m from
 * ext/gemoji/db/emoji.json.
 * The upstream cmark-gfm submodule is intentionally not modified.
 */

#include <ctype.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

#include "emoji_map.h"

static int is_shortcode_char(unsigned char character)
{
    return isalnum(character) || character == '_' ||
        character == '+' || character == '-';
}

static size_t line_indent(const char *line, size_t length)
{
    size_t index = 0;
    while (index < length && index < 3 && line[index] == ' ') {
        ++index;
    }
    return index;
}

static int is_fence_line(const char *line, size_t length,
    char *fence_character, size_t *fence_length)
{
    size_t index = line_indent(line, length);
    size_t run_start = index;

    if (index >= length || (line[index] != '`' && line[index] != '~')) {
        return 0;
    }
    while (index < length && line[index] == line[run_start]) {
        ++index;
    }
    if (index - run_start < 3) {
        return 0;
    }
    *fence_character = line[run_start];
    *fence_length = index - run_start;
    return 1;
}

static int append_bytes(char **output, size_t *length, size_t *capacity,
    const char *bytes, size_t count)
{
    char *grown;
    size_t required = *length + count + 1;

    if (required > *capacity) {
        while (*capacity < required) {
            *capacity *= 2;
        }
        grown = (char *)realloc(*output, *capacity);
        if (grown == NULL) {
            return 0;
        }
        *output = grown;
    }
    memcpy(*output + *length, bytes, count);
    *length += count;
    (*output)[*length] = '\0';
    return 1;
}

static int append_expanded_line(const char *line, size_t length,
    char **output, size_t *output_length, size_t *output_capacity)
{
    size_t index = 0;

    while (index < length) {
        size_t start;
        size_t alias_length;
        const char *replacement;

        if (line[index] == '`') {
            start = index++;
            while (index < length && line[index] == '`') {
                ++index;
            }
            alias_length = index - start;
            while (index < length) {
                if (line[index] == '`') {
                    size_t closing_start = index++;
                    while (index < length && line[index] == '`') {
                        ++index;
                    }
                    if (index - closing_start == alias_length) {
                        break;
                    }
                } else {
                    ++index;
                }
            }
            if (!append_bytes(output, output_length, output_capacity,
                    line + start, index - start)) {
                return 0;
            }
            continue;
        }

        if (line[index] == '<') {
            start = index;
            while (index < length && line[index] != '>') {
                ++index;
            }
            if (index < length) {
                ++index;
            }
            if (!append_bytes(output, output_length, output_capacity,
                    line + start, index - start)) {
                return 0;
            }
            continue;
        }

        if (line[index] == ']' && index + 1 < length &&
                line[index + 1] == '(') {
            start = index;
            index += 2;
            while (index < length && line[index] != ')') {
                ++index;
            }
            if (index < length) {
                ++index;
            }
            if (!append_bytes(output, output_length, output_capacity,
                    line + start, index - start)) {
                return 0;
            }
            continue;
        }

        if (line[index] == ':' &&
                (index == 0 || line[index - 1] != '\\')) {
            start = index + 1;
            index = start;
            while (index < length && is_shortcode_char((unsigned char)line[index])) {
                ++index;
            }
            if (index > start && index < length && line[index] == ':') {
                alias_length = index - start;
                replacement = cmark_gfm_emoji_lookup(line + start, alias_length);
                if (replacement != NULL) {
                    if (!append_bytes(output, output_length, output_capacity,
                            replacement, strlen(replacement))) {
                        return 0;
                    }
                    ++index;
                    continue;
                }
            }
            index = start - 1;
        }

        if (!append_bytes(output, output_length, output_capacity,
                line + index, 1)) {
            return 0;
        }
        ++index;
    }
    return 1;
}

char *cmark_gfm_expand_emojis(const char *markdown, size_t length,
    size_t *expanded_length)
{
    char *output;
    size_t output_length = 0;
    size_t output_capacity = length + 1;
    size_t line_start = 0;
    char fence_character = '\0';
    size_t fence_length = 0;

    if (output_capacity < 64) {
        output_capacity = 64;
    }
    output = (char *)malloc(output_capacity);
    if (output == NULL) {
        return NULL;
    }
    output[0] = '\0';
    if (length == 0) {
        *expanded_length = 0;
        return output;
    }

    while (line_start < length || (length == 0 && line_start == 0)) {
        size_t line_end = line_start;
        size_t content_length;
        int line_is_fence;
        char line_fence_character = '\0';
        size_t line_fence_length = 0;
        int fence_active = fence_length != 0;

        while (line_end < length && markdown[line_end] != '\n') {
            ++line_end;
        }
        content_length = line_end - line_start;
        line_is_fence = is_fence_line(markdown + line_start, content_length,
            &line_fence_character, &line_fence_length);

        if (fence_active) {
            if (line_is_fence &&
                    line_fence_character == fence_character &&
                    line_fence_length >= fence_length) {
                if (!append_bytes(&output, &output_length, &output_capacity,
                        markdown + line_start, content_length)) {
                    free(output);
                    return NULL;
                }
                fence_length = 0;
            } else if (!append_bytes(&output, &output_length, &output_capacity,
                    markdown + line_start, content_length)) {
                free(output);
                return NULL;
            }
        } else if (line_is_fence) {
            fence_character = line_fence_character;
            fence_length = line_fence_length;
            if (!append_bytes(&output, &output_length, &output_capacity,
                    markdown + line_start, content_length)) {
                free(output);
                return NULL;
            }
        } else if (content_length == 0 || markdown[line_start] == '\t' ||
                (content_length >= 4 &&
                    markdown[line_start] == ' ' && markdown[line_start + 1] == ' ' &&
                    markdown[line_start + 2] == ' ' && markdown[line_start + 3] == ' ')) {
            if (!append_bytes(&output, &output_length, &output_capacity,
                    markdown + line_start, content_length)) {
                free(output);
                return NULL;
            }
        } else {
            if (!append_expanded_line(markdown + line_start, content_length,
                    &output, &output_length, &output_capacity)) {
                free(output);
                return NULL;
            }
        }

        if (line_end < length) {
            if (!append_bytes(&output, &output_length, &output_capacity,
                    "\n", 1)) {
                free(output);
                return NULL;
            }
            line_start = line_end + 1;
        } else {
            line_start = length;
        }
    }

    *expanded_length = output_length;
    return output;
}
